import{_ as a,o as l,c as t,a5 as i}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"MM理论","description":"","frontmatter":{"date":"2019-04-19T09:38:53","title":"MM理论","categories":["金融"],"tags":["MM理论"]},"headers":[{"level":2,"title":"概要","slug":"概要","link":"#概要","children":[]},{"level":2,"title":"推论","slug":"推论","link":"#推论","children":[]},{"level":2,"title":"为什么是地平线理论","slug":"为什么是地平线理论","link":"#为什么是地平线理论","children":[]},{"level":2,"title":"思考","slug":"思考","link":"#思考","children":[]},{"level":2,"title":"来源","slug":"来源","link":"#来源","children":[]}],"relativePath":"posts/finance/mm-theory.md","filePath":"posts/finance/mm-theory.md"}'),r={name:"posts/finance/mm-theory.md"};function o(n,e,s,h,c,d){return l(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>MM理论被称为是“公司金融学奠基石的理论”，这个理论是关于融资决策的。香帅把这个理论称为企业融资的地平线理论。</p><p>两个M分别是两位作者名字的首个字母，米勒Miller和莫迪利亚尼Modiogian。米勒也因为他在MM理论中的贡献，在1990年和马科维茨、夏普分享了诺贝尔奖。莫迪利亚尼是因为在之前过世了，所以没有拿到诺奖。</p><h2 id="推论" tabindex="-1">推论 <a class="header-anchor" href="#推论" aria-label="Permalink to &quot;推论&quot;">​</a></h2><ul><li>一个企业的市场价格决定于它未来能创造的价值。</li><li>在有税收存在的情况下，一个企业的价值会随着债务比例的上升而上升。而增加的那部分价值，就恰好等于利息乘以公司的税率。</li><li>当债务存在着破产风险的时候，一个企业的价值会随着债务比例的上升而下降，而下降的价值就等于公司总价值乘以破产的概率。</li></ul><h2 id="为什么是地平线理论" tabindex="-1">为什么是地平线理论 <a class="header-anchor" href="#为什么是地平线理论" aria-label="Permalink to &quot;为什么是地平线理论&quot;">​</a></h2><p>这个理论看起来挺简单的，为什么这么一个听上去很简单的理论，就拿了诺奖，而且还被誉为“公司金融的奠基性的理论呢”？</p><p>一个好理论的评价标准就是能否用一个最简洁（parsimonious）的框架模型解释最多（rich）的现象。</p><p>MM定理很明显，完美地做到了这点，它先假设一个没有摩擦的世界，然后一步步地加入这个摩擦，让你可以估算这个摩擦对公司价值的影响。然后从里作为起点，你就可以动态地思考下去，用这个理论作为标尺（benchmark），去度量和评估不同条件下的融资决策。从一个最简洁，最干净的设定，得到最丰富的现实解释。这是理论的力量，也是MM定理做得特别好的地方。</p><p>那更牛的地方在哪里呢？就是在MM定理动态演化发展的过程中，学界慢慢形成了一套企业投融资角度的体系化思想。比如说在股东价值最大化的目标下，我们该如何投资项目，该如何选择融资结构，该怎么考虑分红政策，分司的内部治理，哪种选择会更加提升公司的价值。这也是为什么香帅会说MM定理就像公司的地平线理论。</p><h2 id="思考" tabindex="-1">思考 <a class="header-anchor" href="#思考" aria-label="Permalink to &quot;思考&quot;">​</a></h2><p>金融学思维和架构设计的思维有时是相关的，比如KISS，Less Is More。基于一个好理论的评价标准，我们能否用来定义一个好技术架构呢？用一个最简单的框架服务最多的应用场景。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文为我对《香帅的北大金融学课》的摘抄和整理，更多详细内容请在得到订阅的《香帅的北大金融学课》。</p>',14)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
